import unittest

from handoff_demo.release_note import normalize_title, render_release_note


class HiddenTests(unittest.TestCase):
    def test_completed_title_contract_is_preserved(self):
        self.assertEqual(normalize_title("  Release   Notes  "), "Release Notes")
        self.assertEqual(normalize_title("RC_2"), "RC_2")

    def test_agreed_next_step_escapes_body_only(self):
        self.assertEqual(render_release_note(" Release  Notes ", 'A&B <x> "quoted"'), 'Release Notes\nA&amp;B &lt;x&gt; "quoted"\n-- generated')
        self.assertEqual(render_release_note("RC_2", "line1\nline2"), "RC_2\nline1\nline2\n-- generated")


if __name__ == "__main__":
    unittest.main()
